-- ============================================================
-- macOS mode
-- Auto-generated by toggle_macos.sh; do not edit manually.
-- ============================================================

hl.window_rule({
    name = "macos-mode-global",
    match = { class = ".*" },
    float = true,
    center = true,
    size = { "1280", "800" },
    persistent_size = true,
})

hl.config({
    general = {
        gaps_out = {
            top = 2,
            right = 12,
            bottom = 80,
            left = 12,
        },
    },
})

-- The whole floating mode remains functional even if Hyprbars
-- is unavailable. The plugin must be loaded before reloading
-- Hyprland for this block to run.
if hl.plugin.hyprbars then
    hl.config({
        plugin = {
            hyprbars = {
                enabled = true,
                bar_height = 34,
                bar_color = "rgba(253341e8)",
                bar_blur = true,
                bar_part_of_window = true,
                bar_precedence_over_border = true,
                bar_title_enabled = true,
                bar_text_align = "center",
                bar_text_size = 12,
                bar_text_weight = 500,
                bar_text_font = "Noto Sans",
                bar_buttons_alignment = "left",
                bar_padding = 14,
                bar_button_padding = 7,
                -- No glyphs; stock Hyprbars has no per-button hover
                -- background/tint setting (requires a custom plugin).
                icon_on_hover = false,
                buttons_on_hover = false,
                inactive_button_color = "rgb(777777)",
                on_double_click = "/home/javier/.config/hypr/scripts/macos_maximize.sh",
            },
        },
    })

    -- Mac order (left to right): close, minimize, maximize.
    -- Keep the circles clean, with no glyphs even on hover.
    hl.plugin.hyprbars.add_button({
        bg_color = "rgb(ff5f57)",
        fg_color = "rgb(471a18)",
        size = 13,
        icon = "",
        action = "hyprctl dispatch 'hl.dsp.window.close()'",
    })

    hl.plugin.hyprbars.add_button({
        bg_color = "rgb(febc2e)",
        fg_color = "rgb(654b10)",
        size = 13,
        icon = "",
        action = "/home/javier/.config/hypr/scripts/macos_minimize.sh",
    })

    hl.plugin.hyprbars.add_button({
        bg_color = "rgb(28c840)",
        fg_color = "rgb(124d20)",
        size = 13,
        icon = "",
        action = "/home/javier/.config/hypr/scripts/macos_maximize.sh",
    })
end
